using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// The default-web options include the default reflection-based resolver,
// so GetTypeInfo<T> will succeed for any serialisable type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type info for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialised with typed metadata: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// With a resolver that only knows about Person, TryGetTypeInfo lets us
// branch safely instead of catching InvalidOperationException.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

if (restrictedOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded — {found!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false");
}

// Now try a type the resolver *cannot* handle: an unregistered source-gen
// context will return false rather than throw.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers
};

if (emptyOptions.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person> unexpectedly succeeded");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false (no resolver) — no exception thrown!");
}

// --- record used above ---
public record Person(string Name, int Age);

